def ordinalTailExtension (α β : Ordinal.{u}) : OrdinalC 𝕜 α →L[𝕜] OrdinalC 𝕜 α :=
  (ContinuousLinearMap.id 𝕜 (OrdinalC 𝕜 α) - ordinalHeadProjection α β).comp
    (ordinalTailPrecompose α (ordinalTailSubtract α β))

